L["Tailoring"] = "Alfaiataria"
L["Take it off this card."] = "Tirá-la deste cartão."
L["Take it off this rule."] = "Tirá-lo desta regra."
L["Takes off the piece before the cursor."] = "Remove o trecho antes do cursor."
L["Takes the bars out and brings them back in, as at a fight's start and end."] = "Tira as barras e as traz de volta, como no começo e no fim de uma luta."
L["Takes this icon off the wheel."] = "Tira este ícone da roda."
L["Talent calculator"] = "Calculadora de talentos"
